DECLARE
 v_batch jsonb := $payload_3ece8642be4470aa${"approval":{"path":"/Users/switkowski/Projects/Testero/hq/drafts/variants/subagent-review-r5-2026-10-19.md","sha256":"2ab2f0f82534643ab8549baeb0a2fb7524c8f5c2946b138e133d3e7f8a0b4d82"},"artifacts":[{"path":"/Users/switkowski/Projects/Testero/frontend.prime-testero-variants-1019/content-pipeline/.cache/variants/repair-r5-live.json","sha256":"7a8dbedfd7c4cd16896134586463b435832db677de06aa87e6a24ddfa628a5ac"}],"runs":[{"id":"fa8972f4-f5b0-5808-99e0-c3fa501b845f","exam":"GCP_PM_ML_ENG","domain_code":"SERVING_AND_SCALING_MODELS","target_count":2,"generated_count":1,"model":"codex","prompt_version":"registry-grounded-v1","notes":"{\"artifact\":\"repair-r5-live.json\",\"artifact_sha256\":\"7a8dbedfd7c4cd16896134586463b435832db677de06aa87e6a24ddfa628a5ac\",\"cert_id\":\"machine-learning-engineer\",\"founder_approval_sha256\":\"2ab2f0f82534643ab8549baeb0a2fb7524c8f5c2946b138e133d3e7f8a0b4d82\",\"judge_model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\"}"},{"id":"ee9e6202-ed67-538d-a7e3-9034f37d0633","exam":"GCP_PM_ML_ENG","domain_code":"AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES","target_count":2,"generated_count":1,"model":"codex","prompt_version":"registry-grounded-v1","notes":"{\"artifact\":\"repair-r5-live.json\",\"artifact_sha256\":\"7a8dbedfd7c4cd16896134586463b435832db677de06aa87e6a24ddfa628a5ac\",\"cert_id\":\"machine-learning-engineer\",\"founder_approval_sha256\":\"2ab2f0f82534643ab8549baeb0a2fb7524c8f5c2946b138e133d3e7f8a0b4d82\",\"judge_model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\"}"}],"questions":[{"question":{"exam":"GCP_PM_ML_ENG","domain_id":"FROM_PARENT","stem":"Your organization's hospital operations team transcribes staff training recordings so employees can search operational procedures. Its CPU inference container runs as a Cloud Run service, and an upload handler waits for each transcript before saving it. As more departments adopt the application, uploads now include full-day training workshops alongside short briefings. Investigating missing workshop transcripts reveals that processing takes several hours and the requests time out before results return. You want to complete each transcription while minimizing infrastructure management. Which approach should you use?","difficulty":"MEDIUM","status":"ACTIVE","review_status":"GOOD","review_notes":"{\"content_pipeline_judge\":{\"version\":1,\"passed\":true,\"score\":0.82,\"reason\":\"All three independent gates passed\",\"model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\"},\"grounding\":{\"cert_id\":\"machine-learning-engineer\",\"objective_id\":\"machine-learning-engineer:standard:4.1:1\",\"guide_sha256\":\"bee925a0fb365488f57fee26b1fca8cdfc82e67fdb8753afb0472c2d3b257701\",\"generator_model\":\"codex\",\"judge_model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\",\"evidence\":[{\"option_label\":\"A\",\"url\":\"https://docs.cloud.google.com/kubernetes-engine/docs/concepts/gke-and-cloud-run\",\"quote\":\"Google Cloud manages the underlying infrastructure and provides tools for simplifying cluster operations, but you're still responsible for the core Kubernetes aspects.\",\"retrieved_at\":\"2026-10-17T12:47:11.597543+00:00\",\"text_sha256\":\"c73b237428481bf533e8a9b856dbe6433e341e37d7d834751372dc2521787d01\"},{\"option_label\":\"B\",\"url\":\"https://docs.cloud.google.com/architecture/choose-agentic-ai-architecture-components\",\"quote\":\"Compute Engine: Compute Engine is an infrastructure as a service (IaaS) product that is suitable for legacy applications. It introduces significant operational overhead compared to modern, container-based runtimes.\",\"retrieved_at\":\"2026-10-17T12:45:36.270165+00:00\",\"text_sha256\":\"18d086e0d847eb15a16b92bcf8c8948a12e29ca5e423c0004b1a5d20b4e425c5\"},{\"option_label\":\"C\",\"url\":\"https://docs.cloud.google.com/run/docs/create-jobs?hl=it\",\"quote\":\"Puoi modificare il valore predefinito modificando l'impostazione del timeout dell'attivit\\u00e0, fino a 168 ore (7 giorni).\",\"retrieved_at\":\"2026-10-17T12:48:22.603817+00:00\",\"text_sha256\":\"e87ac0a62b30c974d57014ff946d6459e02db055351516f4ee5e0fa181870898\"},{\"option_label\":\"D\",\"url\":\"https://docs.cloud.google.com/architecture/choose-agentic-ai-architecture-components\",\"quote\":\"Additionally, the maximum request timeout for Cloud Run services is up to one hour, which might constrain long-running agentic tasks.\",\"retrieved_at\":\"2026-10-17T12:45:36.270165+00:00\",\"text_sha256\":\"18d086e0d847eb15a16b92bcf8c8948a12e29ca5e423c0004b1a5d20b4e425c5\"}],\"mechanical_check\":{\"passed\":true,\"errors\":[]},\"gate_version\":5,\"rules_version\":5,\"gate_verdicts\":{\"style\":{\"verdict\":\"PASS\",\"score\":0.82,\"reason\":\"Sound decision: hours-long batch work fits Cloud Run jobs better than service timeouts, Compute Engine, or GKE. Moment explains discovery and fits the want. Option C's longer timeout loses on product knowledge, though B and D mostly lose to the minimal-management want.\",\"decision_level\":true,\"no_hidden_gotcha\":true,\"current_names\":true,\"distractors_plausible\":true,\"distractors_need_knowledge\":true,\"options_distinct_approaches\":true,\"scenario_clear\":true,\"business_context\":true,\"constraints_as_wants\":true,\"decisions_not_syntax\":true,\"product_knowledge_hinge\":true,\"cloud_specific_alternative\":true,\"generic_validation_key\":false,\"moment_explains_discovery\":true,\"moment_fits_want\":true,\"no_unique_want_echo\":true},\"evidence\":{\"verdict\":\"PASS\",\"score\":0.9,\"reason\":\"Docs support: Cloud Run job task timeout up to 168h (CPU; GPU 1h), services max one hour, GKE leaves core Kubernetes duties, Compute Engine has significant operational overhead. Multi-hour CPU transcription of full-day workshops is plausible. Each distractor loses for a sound reason.\",\"correct_answer_accurate\":true,\"distractors_incorrect\":true,\"explanations_accurate\":true,\"evidence_supported\":true,\"no_credible_second_answer\":true,\"scenario_relevant\":true,\"supported_decision_hinge\":true,\"industry_realism\":true,\"distractor_industry_losing_premises\":true},\"blind_solver\":{\"verdict\":\"PASS\",\"choice\":\"A\",\"confidence\":0.85,\"ambiguous_answers\":false,\"reason\":\"Cloud Run jobs suit long-running batch work with long task timeouts (up to 24h) and no servers to manage, and the container is reused. Raising the request timeout (C) is capped at 60 minutes and can't cover multi-hour runs. B and D need more infrastructure management.\"},\"argon\":{\"model\":\"openrouter/google/gemini-4-argon\",\"version\":2,\"request_sha256\":\"04f0cf6c945d61ffa7a44f0f9bbb5ccac5f55271aec78841661ffde4b794d4e4\",\"review\":{\"verdict\":\"PASS\",\"key_correct\":true,\"other_defensible_option\":false,\"issues\":[],\"fix\":\"No changes needed\"}}},\"parent_question_id\":\"a31d11b8-8dd5-55ed-9ba4-a4b4e8400bcf\",\"variant\":{\"version\":1,\"parent_question_id\":\"a31d11b8-8dd5-55ed-9ba4-a4b4e8400bcf\",\"parent_snapshot_sha256\":\"ed00a9ba04d1f4dd2b547168031e2853df58baf8ad09006c15f79e93d179b1a5\",\"decision_sha256\":\"3ca8fa5d2f2671ca4e8179dcf2b0b4f7d5c4fa6efd7010c1b879b0a38b38e9e6\",\"ordinal\":1,\"surface\":{\"industry\":\"hospital operations\",\"setting\":\"A hospital operations team transcribes full-day staff training workshops and short operational briefings to make procedures searchable for employees.\"},\"family_stem_threshold\":0.45},\"argon\":{\"model\":\"openrouter/google/gemini-4-argon\",\"version\":2,\"request_sha256\":\"04f0cf6c945d61ffa7a44f0f9bbb5ccac5f55271aec78841661ffde4b794d4e4\",\"review\":{\"verdict\":\"PASS\",\"key_correct\":true,\"other_defensible_option\":false,\"issues\":[],\"fix\":\"No changes needed\"}},\"decision_objective\":{\"objective_id\":\"machine-learning-engineer:standard:4.1:1\",\"objective_text\":\"Deploying models for batch and online inference using appropriate services (e.g., Agent Platform, Model Garden, Cloud Run, and GKE)\"},\"decision_plan\":{\"objective_id\":\"machine-learning-engineer:standard:4.1:1\",\"engineering_decision\":\"Choose the execution service for long-running transcription inference after a recent Cloud Run service deployment.\",\"business_consequence\":\"Complete transcripts of city council recordings so residents can search proceedings, while limiting infrastructure management.\",\"existing_system\":\"You are maintaining a transcription application that makes city council recordings searchable. Your team recently deployed its CPU inference container as a Cloud Run service. An upload handler calls the service for each recording and stores the returned transcript. Some recordings take several hours to process, and these requests time out before transcripts return. You want to complete each transcription while minimizing infrastructure management. What should you do?\",\"decisive_constraints\":[\"You want to complete each transcription while minimizing infrastructure management.\"],\"best_action\":\"Run transcription as a Cloud Run job that saves its output, triggering one execution for each uploaded recording.\",\"mistakes\":[{\"action\":\"Keep transcription in a Cloud Run service and extend its request timeout so each recording finishes within the upload handler's request.\",\"scenario_reason\":\"Cloud Run services have a maximum request timeout of 60 minutes. Increasing that timeout cannot accommodate several hours of inference within one request; a job provides managed execution through task completion.\"},{\"action\":\"Move the transcription container to GKE and create a Kubernetes Job for each recording, managing the cluster and its processing capacity.\",\"scenario_reason\":\"Kubernetes Jobs can run this inference, but introduce cluster and capacity management. Cloud Run jobs accommodate the existing container's long-running CPU work with less infrastructure management.\"},{\"action\":\"Deploy the transcription container on Compute Engine workers and distribute recordings through a queue, managing worker scaling and recovery after failures.\",\"scenario_reason\":\"Compute Engine workers can process recordings for several hours, but the team would own worker lifecycle, scaling, and recovery. Cloud Run jobs provide managed task execution for this upload-triggered workload.\"}]},\"decision_proof\":{\"supported\":true,\"uniquely_best\":true,\"scenario_reasons_supported\":true,\"no_feature_gotchas\":true,\"reason\":\"A best fits several-hour CPU batch inference with minimal infrastructure management. B retains an unsuitable synchronous request lifecycle; C and D add infrastructure responsibilities. Implementation requires a run-to-completion entrypoint, persistent output storage, and a task timeout covering the recording's processing time. The supplied documentation supports these requirements without relying on a narrow support exception.\",\"reasons\":[{\"option_label\":\"A\",\"url\":\"https://docs.cloud.google.com/run/docs/create-jobs?hl=it\",\"quote\":\"Puoi modificare il valore predefinito modificando l'impostazione del timeout dell'attivit\\u00e0, fino a 168 ore (7 giorni).\",\"scenario_reason\":\"Cloud Run jobs support task timeouts long enough for several-hour CPU transcription. Triggering an execution per upload and persisting its transcript decouples completion from the upload handler's HTTP request.\"},{\"option_label\":\"B\",\"url\":\"https://docs.cloud.google.com/architecture/choose-agentic-ai-architecture-components\",\"quote\":\"Additionally, the maximum request timeout for Cloud Run services is up to one hour, which might constrain long-running agentic tasks.\",\"scenario_reason\":\"Extending the service request timeout cannot keep a synchronous request open for several hours. The workload needs execution independent of that request lifecycle.\"},{\"option_label\":\"C\",\"url\":\"https://docs.cloud.google.com/kubernetes-engine/docs/concepts/gke-and-cloud-run\",\"quote\":\"Google Cloud manages the underlying infrastructure and provides tools for simplifying cluster operations, but you're still responsible for the core Kubernetes aspects.\",\"scenario_reason\":\"GKE can execute containerized batch work, but introduces Kubernetes configuration and operational responsibilities that are unnecessary when minimizing infrastructure management is the stated priority.\"},{\"option_label\":\"D\",\"url\":\"https://docs.cloud.google.com/architecture/choose-agentic-ai-architecture-components\",\"quote\":\"It introduces significant operational overhead compared to modern, container-based runtimes.\",\"scenario_reason\":\"Compute Engine workers can accommodate long transcription tasks, but the proposed queue and worker design assigns scaling, lifecycle, and failure recovery responsibilities to the team. Cloud Run jobs provide a better fit for the management constraint.\"}],\"mechanical_check\":{\"passed\":true,\"errors\":[]},\"passed\":true},\"key_length_rank\":4,\"style_policy\":{\"version\":\"5.1\",\"objective_id\":\"machine-learning-engineer:standard:4.1:1\",\"allowance\":null},\"option_order\":{\"A\":\"C\",\"B\":\"D\",\"C\":\"A\",\"D\":\"B\"},\"option_balance\":{\"version\":1,\"population_sha256\":\"33d07cbe59e41bf2c73defe4148c5de5e843f6e372242a115e48a700d406fff3\",\"index\":1}},\"founder_approved_variant\":{\"approval\":{\"path\":\"/Users/switkowski/Projects/Testero/hq/drafts/variants/subagent-review-r5-2026-10-19.md\",\"sha256\":\"2ab2f0f82534643ab8549baeb0a2fb7524c8f5c2946b138e133d3e7f8a0b4d82\"},\"artifact\":\"repair-r5-live.json\",\"artifact_sha256\":\"7a8dbedfd7c4cd16896134586463b435832db677de06aa87e6a24ddfa628a5ac\",\"request_sha256\":\"32f58481fda0b0e16270aa571345671fa6832746b8dd789c0398dc19f464bfd4\",\"verdict_sha256\":\"716e911591f8ed6d2eafe2a103eb7175a2209421ef95336766b8349f0446ad43\",\"industry\":\"hospital operations\"}}","generation_run_id":"fa8972f4-f5b0-5808-99e0-c3fa501b845f","id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","question_type":"single_select","parent_question_id":"a31d11b8-8dd5-55ed-9ba4-a4b4e8400bcf","source_ref":"verified-parent-variant:repair-r5-live.json:d4b10e1f-bfe3-51d6-b74b-4481d2207d19"},"answers":[{"question_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","choice_label":"A","choice_text":"Create a GKE cluster for workshop transcription and submit each uploaded recording as a Kubernetes Job. Configure cluster capacity and save completed transcripts to persistent storage.","is_correct":false,"explanation_text":"This fails the infrastructure management goal. GKE leaves the team responsible for core Kubernetes operations, including cluster configuration and scaling. Cloud Run jobs accommodate these long-running CPU tasks without introducing cluster management."},{"question_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","choice_label":"B","choice_text":"Provision Compute Engine workers to transcribe workshop recordings pulled from a queue. Configure worker scaling, manage their lifecycle, recover failed processing, and save transcripts to persistent storage.","is_correct":false,"explanation_text":"This fails the infrastructure management goal. The proposed Compute Engine architecture assigns worker lifecycle, scaling, and failure recovery to the team. Cloud Run jobs provide managed task execution for the uploaded workshop recordings with fewer infrastructure responsibilities."},{"question_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","choice_label":"C","choice_text":"Deploy the CPU container as a Cloud Run job with a task timeout covering transcription. Start an execution per uploaded workshop recording and save its transcript to persistent storage.","is_correct":true,"explanation_text":"Workshop transcription takes several hours, and infrastructure management should remain minimal. Cloud Run jobs support CPU task timeouts up to 168 hours and run tasks through completion. Starting an execution for each upload and saving the transcript separates processing from the upload request. Cloud Run services limit requests to one hour. GKE and Compute Engine can accommodate the work but introduce infrastructure responsibilities."},{"question_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","choice_label":"D","choice_text":"Increase the Cloud Run service's request timeout to accommodate workshop processing. Have the upload handler maintain its synchronous call and save the transcript when the response arrives.","is_correct":false,"explanation_text":"This fails to complete the several-hour workshop transcriptions within the request. Cloud Run services have a maximum request timeout of one hour, so extending that timeout cannot accommodate this processing duration."}],"explanation":{"question_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","explanation_text":"A: This fails the infrastructure management goal. GKE leaves the team responsible for core Kubernetes operations, including cluster configuration and scaling. Cloud Run jobs accommodate these long-running CPU tasks without introducing cluster management.\n\nB: This fails the infrastructure management goal. The proposed Compute Engine architecture assigns worker lifecycle, scaling, and failure recovery to the team. Cloud Run jobs provide managed task execution for the uploaded workshop recordings with fewer infrastructure responsibilities.\n\nC: Workshop transcription takes several hours, and infrastructure management should remain minimal. Cloud Run jobs support CPU task timeouts up to 168 hours and run tasks through completion. Starting an execution for each upload and saving the transcript separates processing from the upload request. Cloud Run services limit requests to one hour. GKE and Compute Engine can accommodate the work but introduce infrastructure responsibilities.\n\nD: This fails to complete the several-hour workshop transcriptions within the request. Cloud Run services have a maximum request timeout of one hour, so extending that timeout cannot accommodate this processing duration.","doc_links":["https://docs.cloud.google.com/kubernetes-engine/docs/concepts/gke-and-cloud-run","https://docs.cloud.google.com/architecture/choose-agentic-ai-architecture-components","https://docs.cloud.google.com/run/docs/create-jobs?hl=it"]},"domain_code":"SERVING_AND_SCALING_MODELS","industry":"hospital operations","artifact":"repair-r5-live.json"},{"question":{"exam":"GCP_PM_ML_ENG","domain_id":"FROM_PARENT","stem":"Your public transit organization uses a corrosion classifier to prioritize bus maintenance. During a transfer of inspection archives to new storage, technicians replayed labeled photos from newly acquired buses and found more missed corrosion than release evaluations predicted. The running Agent Platform Pipelines workflow randomly partitions photos for training and evaluation; each bus contributes multiple views. You want to estimate performance on buses absent from training while minimizing changes to the running workflow. What should you do?","difficulty":"MEDIUM","status":"ACTIVE","review_status":"GOOD","review_notes":"{\"content_pipeline_judge\":{\"version\":1,\"passed\":true,\"score\":0.84,\"reason\":\"All three independent gates passed\",\"model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\"},\"grounding\":{\"cert_id\":\"machine-learning-engineer\",\"objective_id\":\"machine-learning-engineer:standard:5.1:1\",\"guide_sha256\":\"bee925a0fb365488f57fee26b1fca8cdfc82e67fdb8753afb0472c2d3b257701\",\"generator_model\":\"codex\",\"judge_model\":\"anthropic/claude-sonnet-5.5 via Claude Code subagent\",\"evidence\":[{\"option_label\":\"A\",\"url\":\"https://docs.cloud.google.com/dataflow/docs/notebooks/tfma_beam\",\"quote\":\"TensorFlow Model Analysis (TFMA) is a library for performing model evaluation across different slices of data.\",\"retrieved_at\":\"2026-10-14T12:06:01.649168+00:00\",\"text_sha256\":\"594417333f8f3389ba2551d0e745ce94be0123f74c05a52a719cf8ee7aa1e0ef\"},{\"option_label\":\"B\",\"url\":\"https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/bp-tabular\",\"quote\":\"Similarly, if you want your model to be tuned to make generalized inferences about new users, then make sure that data from a specific user is only contained in a single split of your training data.\",\"retrieved_at\":\"2026-10-14T12:05:50.298736+00:00\",\"text_sha256\":\"373739ef3230340d8052cd46cc25e5fdfc3426568a61d48975811b8a6ad1ed6a\"},{\"option_label\":\"C\",\"url\":\"https://docs.cloud.google.com/architecture/guidelines-for-developing-high-quality-ml-solutions\",\"quote\":\"For example, stratified splitting is relevant to classification tasks, while chronological splitting is relevant to time-series tasks.\",\"retrieved_at\":\"2026-10-14T12:05:53.975027+00:00\",\"text_sha256\":\"f4397f300306e039789f9954d2aed3b6ef21075e8ee581e22a1b590232fcfc51\"},{\"option_label\":\"D\",\"url\":\"https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/data-splits\",\"quote\":\"To ensure that the model can generalize to unseen stores, segregate your datasets by stores. In other words, your test set should include only stores different from the validation set, and the validation set should include only stores different from the training set.\",\"retrieved_at\":\"2026-10-14T12:05:47.639531+00:00\",\"text_sha256\":\"49c4f7355595fcf9af2c4473cac5630b3be75fc20d31d93da21571eddd39a2e5\"}],\"mechanical_check\":{\"passed\":true,\"errors\":[]},\"gate_version\":5,\"rules_version\":5,\"gate_verdicts\":{\"style\":{\"verdict\":\"PASS\",\"score\":0.84,\"reason\":\"Sound group-leakage decision: split by bus so evaluation reflects unseen buses. Newly acquired buses explain the discovery. Distractors (dedup, TFMA slicing, severity balancing) are plausible. Product hinge is modest, and the storage transfer is slightly decorative.\",\"decision_level\":true,\"no_hidden_gotcha\":true,\"current_names\":true,\"distractors_plausible\":true,\"distractors_need_knowledge\":true,\"options_distinct_approaches\":true,\"scenario_clear\":true,\"business_context\":true,\"constraints_as_wants\":true,\"decisions_not_syntax\":true,\"product_knowledge_hinge\":false,\"cloud_specific_alternative\":true,\"generic_validation_key\":false,\"moment_explains_discovery\":true,\"moment_fits_want\":true,\"no_unique_want_echo\":true},\"evidence\":{\"verdict\":\"PASS\",\"score\":0.85,\"reason\":\"Docs support segregating by entity (stores/users) to test generalization to unseen entities; the bus-level split is a small change to the existing split. Stratification, exact-dedupe and TFMA slicing all leave bus overlap. Realistic, and the decision matches the parent's.\",\"correct_answer_accurate\":true,\"distractors_incorrect\":true,\"explanations_accurate\":true,\"evidence_supported\":true,\"no_credible_second_answer\":true,\"scenario_relevant\":true,\"supported_decision_hinge\":true,\"industry_realism\":true,\"distractor_industry_losing_premises\":true},\"blind_solver\":{\"verdict\":\"PASS\",\"choice\":\"A\",\"confidence\":0.93,\"ambiguous_answers\":false,\"reason\":\"Multiple views per bus in random splits leak bus identity between train and eval, inflating recall. Grouping by bus gives a held-out-bus estimate with a minimal pipeline change. The other options keep the leakage.\"},\"argon\":{\"model\":\"openrouter/google/gemini-4-argon\",\"version\":2,\"request_sha256\":\"a2e11b465500d48eb08b48e35a6835faa73546f157a1fa8583777bdda2d1750d\",\"review\":{\"verdict\":\"PASS\",\"key_correct\":true,\"other_defensible_option\":false,\"issues\":[],\"fix\":\"No changes needed\"}}},\"parent_question_id\":\"57b9d0c7-8d93-5858-a699-4fc0afeae507\",\"variant\":{\"version\":1,\"parent_question_id\":\"57b9d0c7-8d93-5858-a699-4fc0afeae507\",\"parent_snapshot_sha256\":\"f089fbdff67f28aaf0c2edd54bb652c518fdbcd22033d876142665b9915972cc\",\"decision_sha256\":\"2883a5d08eb6cf40876fc080c309ee458a922755ab8ef8ed928bab5dca5bcf6f\",\"ordinal\":1,\"surface\":{\"industry\":\"public transit\",\"setting\":\"A public transit organization classifies corrosion in bus inspection photos to prioritize maintenance, with multiple photographic views recorded for each bus.\"},\"family_stem_threshold\":0.45},\"argon\":{\"model\":\"openrouter/google/gemini-4-argon\",\"version\":2,\"request_sha256\":\"a2e11b465500d48eb08b48e35a6835faa73546f157a1fa8583777bdda2d1750d\",\"review\":{\"verdict\":\"PASS\",\"key_correct\":true,\"other_defensible_option\":false,\"issues\":[],\"fix\":\"No changes needed\"}},\"decision_objective\":{\"objective_id\":\"machine-learning-engineer:standard:5.1:1\",\"objective_text\":\"Validating data and models\"},\"decision_plan\":{\"objective_id\":\"machine-learning-engineer:standard:5.1:1\",\"engineering_decision\":\"You are maintaining a recently deployed roof-damage classifier that helps an insurer prioritize inspections. Claims reviewers report more missed damage on newly insured properties than the release evaluation predicted. An Agent Platform Pipelines workflow randomly splits photos for training and evaluation, and each property contributes several photos taken from different angles. You want to estimate performance on newly insured properties while minimizing changes to the running workflow. What should you do?\",\"business_consequence\":\"An optimistic evaluation can approve classifiers that miss damaged roofs on unfamiliar properties, delaying inspections and claims handling.\",\"existing_system\":\"The running workflow trains and evaluates a roof-damage classifier using a random photo-level split. Several distinct photos can depict the same property.\",\"decisive_constraints\":[\"You want to estimate performance on newly insured properties while minimizing changes to the running workflow.\"],\"best_action\":\"Split training and evaluation data by property, retrain the classifier, and gate release on performance for held-out properties.\",\"mistakes\":[{\"action\":\"Stratify the existing photo-level split by damage severity, retrain the classifier, and gate release on recall across severity classes in the evaluation set.\",\"scenario_reason\":\"Stratification balances damage categories but still lets photos of the same property appear in training and evaluation, preserving the source of optimistic performance.\"},{\"action\":\"Remove duplicate photos using image hashes, retain the existing photo-level split, and gate release on the retrained classifier's recall in the cleaned evaluation set.\",\"scenario_reason\":\"Removing exact duplicates leaves different views of the same property across both sets. Evaluation can still reward familiarity with properties rather than generalization to newly insured properties.\"},{\"action\":\"Use TensorFlow Model Analysis to compare damage recall across property types, and gate release on the weakest slice in the current evaluation set.\",\"scenario_reason\":\"Slice analysis can reveal uneven performance, but the existing evaluation set still overlaps training at the property level. Even the weakest slice can give an optimistic estimate for unfamiliar properties.\"}]},\"decision_proof\":{\"supported\":true,\"uniquely_best\":true,\"scenario_reasons_supported\":true,\"no_feature_gotchas\":true,\"reason\":\"A uniquely addresses property-level leakage and estimates generalization to unseen properties with a focused change to the running workflow. B\\u2013D retain property overlap, so their evaluation improvements cannot establish performance on unfamiliar properties. The decision directly tests model validation and requires no unsupported feature exception or container assumption.\",\"reasons\":[{\"option_label\":\"A\",\"url\":\"https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/data-splits\",\"quote\":\"To ensure that the model can generalize to unseen stores, segregate your datasets by stores.\",\"scenario_reason\":\"The same entity-level separation applies to properties: holding out entire properties prevents their other photos from appearing in training and supports evaluation on unfamiliar properties.\"},{\"option_label\":\"B\",\"url\":\"https://docs.cloud.google.com/architecture/guidelines-for-developing-high-quality-ml-solutions\",\"quote\":\"For example, stratified splitting is relevant to classification tasks, while chronological splitting is relevant to time-series tasks.\",\"scenario_reason\":\"Severity stratification is a legitimate classification evaluation technique, but balancing classes does not prevent different photos of one property from crossing the training and evaluation boundary.\"},{\"option_label\":\"C\",\"url\":\"https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/bp-tabular\",\"quote\":\"Similarly, if you want your model to be tuned to make generalized inferences about new users, then make sure that data from a specific user is only contained in a single split of your training data.\",\"scenario_reason\":\"The relevant unit is the property, analogous to the user in this guidance. Removing exact duplicate photos leaves distinct views of the same property available across splits.\"},{\"option_label\":\"D\",\"url\":\"https://docs.cloud.google.com/dataflow/docs/notebooks/tfma_beam\",\"quote\":\"TensorFlow Model Analysis (TFMA) is a library for performing model evaluation across different slices of data.\",\"scenario_reason\":\"TFMA can compare property-type slices, but slicing the current evaluation set does not remove property overlap with training. Even the weakest slice can therefore overestimate performance on unseen properties.\"}],\"mechanical_check\":{\"passed\":true,\"errors\":[]},\"passed\":true},\"key_length_rank\":2,\"style_policy\":{\"version\":\"5.1\",\"objective_id\":\"machine-learning-engineer:standard:5.1:1\",\"allowance\":\"general_ml_mlops\"},\"option_order\":{\"A\":\"D\",\"B\":\"C\",\"C\":\"B\",\"D\":\"A\"},\"option_balance\":{\"version\":1,\"population_sha256\":\"33d07cbe59e41bf2c73defe4148c5de5e843f6e372242a115e48a700d406fff3\",\"index\":0}},\"founder_approved_variant\":{\"approval\":{\"path\":\"/Users/switkowski/Projects/Testero/hq/drafts/variants/subagent-review-r5-2026-10-19.md\",\"sha256\":\"2ab2f0f82534643ab8549baeb0a2fb7524c8f5c2946b138e133d3e7f8a0b4d82\"},\"artifact\":\"repair-r5-live.json\",\"artifact_sha256\":\"7a8dbedfd7c4cd16896134586463b435832db677de06aa87e6a24ddfa628a5ac\",\"request_sha256\":\"460f661843c79c58688df5ab0aa91f943f5d0720ad9c0ad446683ac63e8eb8ed\",\"verdict_sha256\":\"e123bd666902443e17bd740dba35ae5bbe9b02c2cf6eede7f1f230ce9b2f465d\",\"industry\":\"public transit\"}}","generation_run_id":"ee9e6202-ed67-538d-a7e3-9034f37d0633","id":"5fe281b2-b348-5829-ad5a-80de90cd4235","question_type":"single_select","parent_question_id":"57b9d0c7-8d93-5858-a699-4fc0afeae507","source_ref":"verified-parent-variant:repair-r5-live.json:5fe281b2-b348-5829-ad5a-80de90cd4235"},"answers":[{"question_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","choice_label":"A","choice_text":"Apply TensorFlow Model Analysis to measure corrosion recall separately for each bus type in the current evaluation partition, and approve the classifier only when the weakest slice meets the release threshold.","is_correct":false,"explanation_text":"TensorFlow Model Analysis evaluates performance across data slices, but slicing by bus type does not separate individual buses between training and evaluation. Even the weakest slice can reflect familiarity with training buses, so it cannot establish performance on unfamiliar buses."},{"question_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","choice_label":"B","choice_text":"Filter exact duplicate inspection photos using image hashes, keep random photo partitioning, retrain the corrosion classifier, and approve releases according to recall measured on the remaining evaluation photos.","is_correct":false,"explanation_text":"This fails to remove overlap at the bus level. Removing identical photos leaves distinct views of the same bus across training and evaluation. The evaluation still does not represent buses absent from training."},{"question_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","choice_label":"C","choice_text":"Balance corrosion severity across random photo partitions, train another classifier, and base the release decision on its evaluation recall for each corrosion severity category.","is_correct":false,"explanation_text":"This fails to estimate performance on unfamiliar buses. Stratification is appropriate for balancing classification categories, but different views of the same bus can still enter both partitions. Severity-specific recall can therefore remain optimistic."},{"question_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","choice_label":"D","choice_text":"Assign each bus's photos to a single training or evaluation partition, retrain the corrosion classifier, and use recall on held-out buses to decide whether to release it.","is_correct":true,"explanation_text":"The evaluation needs to represent unfamiliar buses with a limited workflow change. Assigning entire buses to separate partitions prevents other views of evaluation buses from entering training. Retraining and evaluating recall on held-out buses then tests the intended generalization. This changes the partitioning in Agent Platform Pipelines rather than replacing the workflow. Severity balancing, exact-duplicate removal, and slice analysis all leave bus overlap unresolved."}],"explanation":{"question_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","explanation_text":"A: TensorFlow Model Analysis evaluates performance across data slices, but slicing by bus type does not separate individual buses between training and evaluation. Even the weakest slice can reflect familiarity with training buses, so it cannot establish performance on unfamiliar buses.\n\nB: This fails to remove overlap at the bus level. Removing identical photos leaves distinct views of the same bus across training and evaluation. The evaluation still does not represent buses absent from training.\n\nC: This fails to estimate performance on unfamiliar buses. Stratification is appropriate for balancing classification categories, but different views of the same bus can still enter both partitions. Severity-specific recall can therefore remain optimistic.\n\nD: The evaluation needs to represent unfamiliar buses with a limited workflow change. Assigning entire buses to separate partitions prevents other views of evaluation buses from entering training. Retraining and evaluating recall on held-out buses then tests the intended generalization. This changes the partitioning in Agent Platform Pipelines rather than replacing the workflow. Severity balancing, exact-duplicate removal, and slice analysis all leave bus overlap unresolved.","doc_links":["https://docs.cloud.google.com/dataflow/docs/notebooks/tfma_beam","https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/bp-tabular","https://docs.cloud.google.com/architecture/guidelines-for-developing-high-quality-ml-solutions","https://docs.cloud.google.com/gemini-enterprise-agent-platform/machine-learning/tabular-data/data-splits"]},"domain_code":"AUTOMATING_AND_ORCHESTRATING_ML_PIPELINES","industry":"public transit","artifact":"repair-r5-live.json"}],"approval_profile":"round5-winners","validation_reports":{"key_length":{"enforced":true,"count":2,"shortest_or_tied_count":0,"unique_longest_count":1,"shortest_or_tied_fraction":0.0,"maximum_shortest_fraction":0.25,"passed":true,"errors":[],"items":[{"candidate_id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","word_counts":[29,27,26,27],"shortest_or_tied":false,"unique_longest":true},{"candidate_id":"5fe281b2-b348-5829-ad5a-80de90cd4235","word_counts":[27,24,28,31],"shortest_or_tied":false,"unique_longest":false}]},"key_position":{"count":2,"counts":{"A":0,"B":0,"C":1,"D":1},"target_max_rate":0.4,"minimum_count":10,"enforced":false,"passed":true},"template_diversity":{"count":1,"generic_count":0,"target_max_rate":0.2,"passed":true},"duplicates":[{"id":"d4b10e1f-bfe3-51d6-b74b-4481d2207d19","report":{"passed":true,"threshold":0.2,"method":"min(stem token Jaccard, correct-option token Jaccard), NFKC/casefold/stopwords","matches":[],"reason":"No near-duplicate scenario and decision","family_stem_threshold":0.45,"family_similarity":[{"matched_id":"a31d11b8-8dd5-55ed-9ba4-a4b4e8400bcf","stem_score":0.3333333333333333,"key_score":0.37037037037037035,"score":0.3333333333333333},{"matched_id":"221bf8b2-e221-5a96-9c47-d993886db178","stem_score":0.34177215189873417,"key_score":0.3333333333333333,"score":0.3333333333333333},{"matched_id":"ff63a277-deb2-5e69-a739-64517f81a912","stem_score":0.32098765432098764,"key_score":0.3793103448275862,"score":0.32098765432098764}],"max_family_stem_similarity":0.34177215189873417,"parent_similarity":{"matched_id":"a31d11b8-8dd5-55ed-9ba4-a4b4e8400bcf","stem_score":0.3333333333333333,"key_score":0.37037037037037035,"score":0.3333333333333333},"family_matches":[],"prior_family_industry_reuse":[]}},{"id":"5fe281b2-b348-5829-ad5a-80de90cd4235","report":{"passed":true,"threshold":0.2,"method":"min(stem token Jaccard, correct-option token Jaccard), NFKC/casefold/stopwords","matches":[],"reason":"No near-duplicate scenario and decision","family_stem_threshold":0.45,"family_similarity":[{"matched_id":"57b9d0c7-8d93-5858-a699-4fc0afeae507","stem_score":0.3384615384615385,"key_score":0.25,"score":0.25},{"matched_id":"20a0b44d-e652-513d-968e-19be6bcc1965","stem_score":0.2602739726027397,"key_score":0.3793103448275862,"score":0.2602739726027397}],"max_family_stem_similarity":0.3384615384615385,"parent_similarity":{"matched_id":"57b9d0c7-8d93-5858-a699-4fc0afeae507","stem_score":0.3384615384615385,"key_score":0.25,"score":0.25},"family_matches":[],"prior_family_industry_reuse":[]}}]}}$payload_3ece8642be4470aa$::jsonb;
 v_row jsonb; v_run jsonb; v_answer jsonb; v_parent record; v_tags jsonb;
 v_count integer; v_tag_count integer;
BEGIN
 IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass('public.questions')
   AND attname='parent_question_id' AND NOT attisdropped) THEN
  RAISE EXCEPTION 'Apply the practice-only parent_question_id migration first';
 END IF;
 IF NOT EXISTS (SELECT 1 FROM pg_attribute WHERE attrelid=to_regclass('public.questions')
   AND attname='question_type' AND NOT attisdropped) THEN
  RAISE EXCEPTION 'Apply the single_select question_type foundation migration first';
 END IF;
 IF to_regclass('public.question_tags') IS NULL OR
    to_regprocedure('public.replace_question_tags(uuid,text,jsonb)') IS NULL THEN
  RAISE EXCEPTION 'Apply the question taxonomy migration first';
 END IF;
 IF jsonb_array_length(v_batch->'questions')<>2 OR
    (SELECT count(DISTINCT x->'question'->>'id') FROM jsonb_array_elements(v_batch->'questions') x)<>2 THEN
  RAISE EXCEPTION 'Expected exactly 2 distinct approved variants';
 END IF;
 -- Serialize the insert/existence check; parent row locks also stabilize tag RPC writers.
 LOCK TABLE public.questions IN SHARE ROW EXCLUSIVE MODE;
 FOR v_row IN SELECT value FROM jsonb_array_elements(v_batch->'questions')
   ORDER BY value->'question'->>'parent_question_id',value->'question'->>'id' LOOP
  IF EXISTS (SELECT 1 FROM public.questions WHERE id=(v_row->'question'->>'id')::uuid) THEN
   RAISE EXCEPTION 'Variant ID already exists: %', v_row->'question'->>'id';
  END IF;
  SELECT q.id,q.domain_id,q.status,q.exam,q.question_type,q.parent_question_id,d.code INTO v_parent
  FROM public.questions q JOIN public.exam_domains d ON d.id=q.domain_id AND d.exam=q.exam
  WHERE q.id=(v_row->'question'->>'parent_question_id')::uuid FOR UPDATE OF q;
  IF NOT FOUND OR v_parent.status IS DISTINCT FROM 'ACTIVE' OR v_parent.exam IS DISTINCT FROM 'GCP_PM_ML_ENG'
     OR v_parent.question_type IS DISTINCT FROM 'single_select'
     OR v_parent.parent_question_id IS NOT NULL OR v_parent.code IS DISTINCT FROM v_row->>'domain_code' THEN
   RAISE EXCEPTION 'Parent missing, inactive, non-original, wrong exam or domain: %', v_row->'question'->>'parent_question_id';
  END IF;
  IF jsonb_array_length(v_row->'answers')<>4 OR
     (SELECT count(DISTINCT x->>'choice_label') FROM jsonb_array_elements(v_row->'answers') x
      WHERE x->>'choice_label' IN ('A','B','C','D'))<>4 OR
     (SELECT count(*) FROM jsonb_array_elements(v_row->'answers') x WHERE (x->>'is_correct')::boolean)<>1 THEN
   RAISE EXCEPTION 'Invalid approved answer set';
  END IF;
 END LOOP;
 FOR v_run IN SELECT value FROM jsonb_array_elements(v_batch->'runs') LOOP
  IF EXISTS (SELECT 1 FROM public.question_generation_runs WHERE id=(v_run->>'id')::uuid) THEN
   RAISE EXCEPTION 'Generation run already exists; reconcile before retry: %', v_run->>'id';
  END IF;
 END LOOP;
 FOR v_run IN SELECT value FROM jsonb_array_elements(v_batch->'runs') LOOP
  INSERT INTO public.question_generation_runs(id,exam,domain_code,target_count,generated_count,model,prompt_version,notes,completed_at)
  VALUES ((v_run->>'id')::uuid,v_run->>'exam',v_run->>'domain_code',(v_run->>'target_count')::int,
    (v_run->>'generated_count')::int,v_run->>'model',v_run->>'prompt_version',v_run->>'notes',now());
 END LOOP;
 FOR v_row IN SELECT value FROM jsonb_array_elements(v_batch->'questions') LOOP
  INSERT INTO public.questions(id,exam,domain_id,stem,difficulty,status,review_status,review_notes,
     generation_run_id,question_type,parent_question_id,source_ref)
  SELECT (v_row->'question'->>'id')::uuid,'GCP_PM_ML_ENG',p.domain_id,v_row->'question'->>'stem',
     v_row->'question'->>'difficulty','ACTIVE','GOOD',v_row->'question'->>'review_notes',
     (v_row->'question'->>'generation_run_id')::uuid,'single_select',p.id,v_row->'question'->>'source_ref'
  FROM public.questions p WHERE p.id=(v_row->'question'->>'parent_question_id')::uuid;
  FOR v_answer IN SELECT value FROM jsonb_array_elements(v_row->'answers') LOOP
   INSERT INTO public.answers(question_id,choice_label,choice_text,is_correct,explanation_text)
   VALUES ((v_row->'question'->>'id')::uuid,v_answer->>'choice_label',v_answer->>'choice_text',
     (v_answer->>'is_correct')::boolean,v_answer->>'explanation_text');
  END LOOP;
  INSERT INTO public.explanations(question_id,explanation_text,doc_links)
  VALUES ((v_row->'question'->>'id')::uuid,v_row->'explanation'->>'explanation_text',v_row->'explanation'->'doc_links');
  SELECT coalesce(jsonb_agg(jsonb_build_object('dimension',dimension,'value_key',value_key,'confidence',confidence)
     ORDER BY dimension,value_key),'[]'::jsonb) INTO v_tags FROM public.question_tags
  WHERE question_id=(v_row->'question'->>'parent_question_id')::uuid;
  PERFORM public.replace_question_tags((v_row->'question'->>'id')::uuid,'generation',v_tags);
  v_tag_count := jsonb_array_length(v_tags);
  SELECT count(*) INTO v_count FROM public.answers WHERE question_id=(v_row->'question'->>'id')::uuid;
  IF v_count<>4 OR NOT EXISTS (SELECT 1 FROM public.explanations WHERE question_id=(v_row->'question'->>'id')::uuid)
     OR (SELECT count(*) FROM public.question_tags WHERE question_id=(v_row->'question'->>'id')::uuid
         AND source='generation')<>v_tag_count THEN
   RAISE EXCEPTION 'Post-insert content/tag verification failed';
  END IF;
  RAISE NOTICE 'Inserted variant %, parent %, industry %, copied % tags',
    v_row->'question'->>'id',v_row->'question'->>'parent_question_id',v_row->>'industry',v_tag_count;
 END LOOP;
END;
$body_3ece8642be4470aa$;
COMMIT;
